fn load_mask_program(path:&str)->MaskProgram{let data=std::fs::read(path).unwrap();assert_eq!(&data[..8],b"MRMASK01");let read64=|off|u64::from_le_bytes(data[off..off+8].try_into().unwrap())as usize;let n=read64(8);let inputs=read64(16);let outputs=read64(24);assert!(n>=2&&n<100000000);assert_eq!(inputs,1024);assert!(outputs==512||outputs==1);assert_eq!(data.len(),32+n*16+outputs*4);let read32=|off|u32::from_le_bytes(data[off..off+4].try_into().unwrap());let mut nodes=Vec::with_capacity(n);for i in 0..n{let off=32+i*16;let node=MaskNode{kind:read32(off),a:read32(off+4),b:read32(off+8),aux:read32(off+12)};assert_eq!(node.aux,0);match node.kind{0|1=>{},2=>assert!((node.a as usize)<inputs),3|4|5=>assert!((node.a as usize)<i&&(node.b as usize)<i),_=>panic!("unknown mask terminal")};nodes.push(node);}let roots=(0..outputs).map(|i|{let r=read32(32+n*16+i*4);assert!((r as usize)<n);r}).collect();MaskProgram{nodes,roots,inputs,old_live:0}}
struct ZeroReader;impl XofReader for ZeroReader{fn read(&mut self,out:&mut[u8]){out.fill(0);}}
fn validation_random(seed:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"mr-mask-independent-protected-v1");h.update(&seed.to_le_bytes());h.finalize_xof()}

fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();assert_eq!(ops.len(),11630716);let old=load_mask_program(&args[2]);let guard=load_mask_program(&args[3]);assert_eq!(old.roots.len(),512);assert_eq!(guard.roots.len(),1);let(nq,nb,_,regs)=analyze_ops(ops.iter());assert_eq!((nq,nb),(1234,45701));let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[4]).unwrap().lines().map(|l|l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v,16).unwrap()).collect()).collect();assert_eq!(rows.len(),445);assert!(rows.iter().all(|r|r.len()==6));let mut flags=Vec::new();let timer=std::time::Instant::now();
 for (batch,data)in rows.chunks(64).enumerate(){let mut random=ZeroReader;let mut sim=Simulator::new(nq as usize,nb as usize,&mut random);let mut expected=vec![0u64;512];for(lane,row)in data.iter().enumerate(){for(reg,value)in regs[..4].iter().zip(&row[..4]){sim.set_register(reg,*value,lane);}for reg in 0..2{for bit in 0..256{expected[reg*256+bit]|=(row[4+reg].bit(bit)as u64)<<lane;}}}let input:Vec<u64>=regs.iter().flatten().map(|w|match w{QubitOrBit::Qubit(id)=>sim.qubits[id.0 as usize],QubitOrBit::Bit(id)=>sim.bits[id.0 as usize]}).collect();let known=old.eval(&input);let safe=guard.eval(&input)[0];sim.apply_iter(ops.iter());let active=if data.len()==64{u64::MAX}else{(1u64<<data.len())-1};let mut wrong=0;for(index,wire)in regs[..2].iter().flatten().enumerate(){let actual=match wire{QubitOrBit::Qubit(id)=>sim.qubits[id.0 as usize],QubitOrBit::Bit(id)=>sim.bits[id.0 as usize]};wrong|=(actual^expected[index])&known[index]&active;}for lane in 0..data.len(){let certified=wrong>>lane&1!=0;let equal=safe>>lane&1!=0;flags.push(serde_json::json!({"index":batch*64+lane,"old_mask_certified_wrong":certified,"conditional_transfer_guard_false":equal,"retained_certificate":certified&&equal}));}}
 let count=|start,end,key:&str|flags[start..end].iter().filter(|x|x[key].as_bool().unwrap()).count();assert_eq!(count(0,431,"old_mask_certified_wrong"),421);let report=serde_json::json!({"status":"EXACT_RETAINED_SUBSET_FROM_ORIGINAL_ZERO_MR_PROTECTED_VALUES_AND_FROZEN_MASKS","old_stream_sha256":"2a522394cdf3e6a0df7784ad4db761030933c1f7ccd0ff8e641d68ec7a4dab3e","original_mask_sha256":"560c12d5044dd895a4ef32adc905cdde48a780a196b3b28a75951c7f27b4fe9d","discrepancy_guard_sha256":"355f9951eda21a7204a96fd391b3208e8d6e000dce6a14feb40d8f19b637f2b3","old431_original_certified":count(0,431,"old_mask_certified_wrong"),"old431_retained":count(0,431,"retained_certificate"),"old431_lost_to_guard":count(0,431,"old_mask_certified_wrong")-count(0,431,"retained_certificate"),"repair14_original_certified_wrong":count(431,445,"old_mask_certified_wrong"),"repair14_retained":count(431,445,"retained_certificate"),"rows":flags,"seconds":timer.elapsed().as_secs_f64(),"not_runtime_authority":"Classification only; conditional source-chain proof and explicit composite manifest remain separate requirements."});println!("{report}");}
